CREATE TABLE IF NOT EXISTS user (
    avatar_url TEXT,
    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
    customer_type TEXT DEFAULT 'individual',
    email TEXT NOT NULL,
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    phone TEXT,
    CONSTRAINT user_customer_type_values CHECK ((customer_type IN ('individual', 'patron', 'organization'))),
    CONSTRAINT user_name_length CHECK ((length(name) >= 1 AND length(name) <= 120))
);

CREATE TABLE IF NOT EXISTS api_key (
    active INTEGER DEFAULT 1,
    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
    expires_at TEXT,
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    key_hash TEXT NOT NULL,
    key_prefix TEXT NOT NULL,
    last_used_at TEXT,
    name TEXT NOT NULL,
    scopes TEXT DEFAULT '*',
    user_id INTEGER NOT NULL REFERENCES user(id),
    CONSTRAINT api_key_active_values CHECK ((active IN ('0', '1'))),
    CONSTRAINT api_key_name_length CHECK ((length(name) <= 120))
);

CREATE TABLE IF NOT EXISTS artist_profile (
    active INTEGER DEFAULT 1,
    bio TEXT,
    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    role TEXT NOT NULL,
    user_id INTEGER NOT NULL REFERENCES user(id)
);

CREATE TABLE IF NOT EXISTS booking (
    amount_pence INTEGER NOT NULL,
    client TEXT DEFAULT 'web',
    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
    currency TEXT DEFAULT 'GBP',
    expires_at TEXT NOT NULL,
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    payment_deadline_at TEXT,
    payment_reference TEXT,
    status TEXT DEFAULT 'checkout_pending',
    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
    user_id INTEGER NOT NULL REFERENCES user(id),
    CONSTRAINT booking_status_values CHECK ((status IN ('checkout_pending', 'payment_pending', 'paid', 'expired', 'cancelled', 'refund_required', 'refunded')))
);

CREATE TABLE IF NOT EXISTS production (
    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
    description TEXT,
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    season TEXT,
    status TEXT DEFAULT 'planning',
    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT production_name_length CHECK ((length(name) <= 160)),
    CONSTRAINT production_season_length CHECK ((length(season) <= 80)),
    CONSTRAINT production_status_values CHECK ((status IN ('planning', 'active', 'completed', 'cancelled')))
);

CREATE TABLE IF NOT EXISTS venue (
    active INTEGER DEFAULT 1,
    address TEXT NOT NULL,
    capacity INTEGER NOT NULL,
    city TEXT NOT NULL,
    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    postcode TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS performance (
    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
    description TEXT,
    ends_at TEXT NOT NULL,
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    price_pence INTEGER NOT NULL,
    production_id INTEGER NOT NULL REFERENCES production(id),
    starts_at TEXT NOT NULL,
    status TEXT DEFAULT 'scheduled',
    venue_id INTEGER NOT NULL REFERENCES venue(id),
    CONSTRAINT performance_price_pence_range CHECK ((price_pence >= 0)),
    CONSTRAINT performance_status_values CHECK ((status IN ('scheduled', 'cancelled', 'completed'))),
    CONSTRAINT performance_ends_after_start CHECK ((starts_at < ends_at))
);

CREATE TABLE IF NOT EXISTS ticket (
    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    performance_id INTEGER NOT NULL REFERENCES performance(id),
    price_pence INTEGER NOT NULL,
    seat TEXT,
    status TEXT DEFAULT 'reserved',
    ticket_type TEXT DEFAULT 'standard',
    user_id INTEGER NOT NULL REFERENCES user(id),
    CONSTRAINT ticket_price_pence_range CHECK ((price_pence >= 0)),
    CONSTRAINT ticket_seat_length CHECK ((length(seat) <= 24)),
    CONSTRAINT ticket_status_values CHECK ((status IN ('reserved', 'confirmed', 'cancelled', 'used'))),
    CONSTRAINT ticket_ticket_type_values CHECK ((ticket_type IN ('standard', 'concession', 'patron', 'vip'))),
    CONSTRAINT ticket_vip_price_minimum CHECK (((ticket_type != 'vip') OR (price_pence >= 2500)))
);

CREATE TABLE IF NOT EXISTS booking_ticket (
    booking_id INTEGER NOT NULL REFERENCES booking(id),
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    ticket_id INTEGER NOT NULL REFERENCES ticket(id)
);

CREATE TABLE IF NOT EXISTS identity_challenge (
    code_hash TEXT NOT NULL,
    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
    email TEXT NOT NULL,
    expires_at TEXT NOT NULL,
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    ip_address TEXT,
    public_key TEXT NOT NULL,
    used INTEGER DEFAULT 0
);

CREATE TABLE IF NOT EXISTS identity_registry (
    email TEXT NOT NULL,
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    public_key TEXT NOT NULL,
    revoked INTEGER DEFAULT 0,
    verified_at TEXT DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS identity_request_signature (
    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    signature TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS identity_session (
    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
    expires_at TEXT NOT NULL,
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    last_used_at TEXT,
    revoked INTEGER DEFAULT 0,
    token_hash TEXT NOT NULL,
    token_prefix TEXT NOT NULL,
    user_id INTEGER NOT NULL REFERENCES user(id)
);

CREATE TABLE IF NOT EXISTS identity_verification_attempt (
    challenge_id INTEGER NOT NULL,
    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
    email TEXT NOT NULL,
    id INTEGER PRIMARY KEY AUTOINCREMENT
);

CREATE TABLE IF NOT EXISTS production_material (
    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
    description TEXT,
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    kind TEXT DEFAULT 'score',
    name TEXT NOT NULL,
    production_id INTEGER NOT NULL REFERENCES production(id),
    status TEXT DEFAULT 'draft',
    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
    visibility TEXT DEFAULT 'private',
    CONSTRAINT production_material_kind_values CHECK ((kind IN ('score', 'script', 'cut_list', 'rehearsal_note', 'briefing', 'media', 'other'))),
    CONSTRAINT production_material_name_length CHECK ((length(name) <= 160)),
    CONSTRAINT production_material_status_values CHECK ((status IN ('draft', 'current', 'archived'))),
    CONSTRAINT production_material_visibility_values CHECK ((visibility IN ('private', 'participants', 'public')))
);

CREATE TABLE IF NOT EXISTS material_version (
    checksum TEXT,
    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
    created_by_user_id INTEGER REFERENCES user(id),
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    material_id INTEGER NOT NULL REFERENCES production_material(id),
    notes TEXT,
    status TEXT DEFAULT 'draft',
    storage_uri TEXT NOT NULL,
    version_label TEXT NOT NULL,
    CONSTRAINT material_version_status_values CHECK ((status IN ('draft', 'current', 'superseded', 'archived'))),
    CONSTRAINT material_version_version_label_length CHECK ((length(version_label) <= 80))
);

CREATE TABLE IF NOT EXISTS performance_artist (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    performance_id INTEGER NOT NULL REFERENCES performance(id),
    role_in_performance TEXT,
    user_id INTEGER NOT NULL REFERENCES user(id)
);

CREATE TABLE IF NOT EXISTS production_role (
    category TEXT DEFAULT 'cast',
    description TEXT,
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    production_id INTEGER NOT NULL REFERENCES production(id),
    required_count INTEGER DEFAULT 1,
    status TEXT DEFAULT 'open',
    CONSTRAINT production_role_category_values CHECK ((category IN ('cast', 'creative', 'crew', 'orchestra', 'admin'))),
    CONSTRAINT production_role_name_length CHECK ((length(name) <= 120)),
    CONSTRAINT production_role_required_count_range CHECK ((required_count >= 1)),
    CONSTRAINT production_role_status_values CHECK ((status IN ('open', 'filled', 'withdrawn')))
);

CREATE TABLE IF NOT EXISTS production_member (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    production_id INTEGER NOT NULL REFERENCES production(id),
    responsibility TEXT,
    role_id INTEGER REFERENCES production_role(id),
    status TEXT DEFAULT 'confirmed',
    user_id INTEGER NOT NULL REFERENCES user(id),
    CONSTRAINT production_member_status_values CHECK ((status IN ('invited', 'confirmed', 'declined', 'released')))
);

CREATE TABLE IF NOT EXISTS rehearsal (
    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
    ends_at TEXT NOT NULL,
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    notes TEXT,
    production_id INTEGER NOT NULL REFERENCES production(id),
    starts_at TEXT NOT NULL,
    status TEXT DEFAULT 'draft',
    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
    venue_id INTEGER REFERENCES venue(id),
    CONSTRAINT rehearsal_name_length CHECK ((length(name) <= 160)),
    CONSTRAINT rehearsal_status_values CHECK ((status IN ('draft', 'published', 'completed', 'cancelled'))),
    CONSTRAINT rehearsal_ends_after_start CHECK ((starts_at < ends_at))
);

CREATE TABLE IF NOT EXISTS rehearsal_call (
    call_status TEXT DEFAULT 'called',
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    notes TEXT,
    rehearsal_id INTEGER NOT NULL REFERENCES rehearsal(id),
    role_id INTEGER REFERENCES production_role(id),
    user_id INTEGER NOT NULL REFERENCES user(id),
    CONSTRAINT rehearsal_call_call_status_values CHECK ((call_status IN ('called', 'confirmed', 'declined', 'attended', 'absent')))
);

CREATE TABLE IF NOT EXISTS rehearsal_requirement (
    category TEXT DEFAULT 'scene',
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    production_id INTEGER NOT NULL REFERENCES production(id),
    required_sessions INTEGER DEFAULT 1,
    status TEXT DEFAULT 'open',
    CONSTRAINT rehearsal_requirement_category_values CHECK ((category IN ('scene', 'act', 'role', 'ensemble', 'technical', 'music'))),
    CONSTRAINT rehearsal_requirement_name_length CHECK ((length(name) <= 160)),
    CONSTRAINT rehearsal_requirement_required_sessions_range CHECK ((required_sessions >= 1)),
    CONSTRAINT rehearsal_requirement_status_values CHECK ((status IN ('open', 'scheduled', 'covered', 'dropped')))
);

CREATE TABLE IF NOT EXISTS rehearsal_coverage (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    notes TEXT,
    rehearsal_id INTEGER NOT NULL REFERENCES rehearsal(id),
    requirement_id INTEGER NOT NULL REFERENCES rehearsal_requirement(id),
    status TEXT DEFAULT 'planned',
    CONSTRAINT rehearsal_coverage_status_values CHECK ((status IN ('planned', 'covered', 'deferred')))
);

CREATE TABLE IF NOT EXISTS [transaction] (
    amount_pence INTEGER NOT NULL,
    client TEXT DEFAULT 'web',
    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    reference TEXT,
    status TEXT DEFAULT 'pending',
    type TEXT NOT NULL,
    user_id INTEGER NOT NULL REFERENCES user(id),
    CONSTRAINT transaction_status_values CHECK ((status IN ('pending', 'authorized', 'completed', 'failed', 'cancelled', 'refund_required', 'refunded')))
);

CREATE TABLE IF NOT EXISTS transaction_ticket (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    ticket_id INTEGER NOT NULL REFERENCES ticket(id),
    transaction_id INTEGER NOT NULL REFERENCES [transaction](id)
);

CREATE UNIQUE INDEX IF NOT EXISTS booking_unique_payment_reference ON booking (payment_reference);

CREATE INDEX IF NOT EXISTS booking_by_user_status ON booking (user_id, status);

CREATE UNIQUE INDEX IF NOT EXISTS material_version_unique_material_version ON material_version (material_id, version_label);

CREATE INDEX IF NOT EXISTS material_version_by_created_by_user_status ON material_version (created_by_user_id, status);

CREATE INDEX IF NOT EXISTS material_version_by_material_status ON material_version (material_id, status);

CREATE UNIQUE INDEX IF NOT EXISTS production_member_unique_production_user ON production_member (production_id, user_id);

CREATE INDEX IF NOT EXISTS production_member_by_production_status ON production_member (production_id, status);

CREATE INDEX IF NOT EXISTS production_member_by_role_status ON production_member (role_id, status);

CREATE INDEX IF NOT EXISTS production_member_by_user_status ON production_member (user_id, status);

CREATE UNIQUE INDEX IF NOT EXISTS rehearsal_call_unique_rehearsal_user ON rehearsal_call (rehearsal_id, user_id);

CREATE INDEX IF NOT EXISTS rehearsal_call_by_rehearsal ON rehearsal_call (rehearsal_id);

CREATE INDEX IF NOT EXISTS rehearsal_call_by_role ON rehearsal_call (role_id);

CREATE INDEX IF NOT EXISTS rehearsal_call_by_user ON rehearsal_call (user_id);

CREATE UNIQUE INDEX IF NOT EXISTS rehearsal_coverage_unique_requirement_rehearsal ON rehearsal_coverage (requirement_id, rehearsal_id);

CREATE INDEX IF NOT EXISTS rehearsal_coverage_by_rehearsal_status ON rehearsal_coverage (rehearsal_id, status);

CREATE INDEX IF NOT EXISTS rehearsal_coverage_by_requirement_status ON rehearsal_coverage (requirement_id, status);

CREATE UNIQUE INDEX IF NOT EXISTS ticket_unique_performance_seat ON ticket (performance_id, seat);

CREATE INDEX IF NOT EXISTS ticket_by_performance_status ON ticket (performance_id, status);

CREATE INDEX IF NOT EXISTS ticket_by_user_status ON ticket (user_id, status);

CREATE UNIQUE INDEX IF NOT EXISTS transaction_unique_reference ON [transaction] (reference);

CREATE INDEX IF NOT EXISTS transaction_by_user_status ON [transaction] (user_id, status);

CREATE UNIQUE INDEX IF NOT EXISTS user_unique_email ON user (email);

CREATE UNIQUE INDEX IF NOT EXISTS artist_profile_unique_user ON artist_profile (user_id);

CREATE UNIQUE INDEX IF NOT EXISTS booking_ticket_unique_pair ON booking_ticket (booking_id, ticket_id);

CREATE UNIQUE INDEX IF NOT EXISTS booking_ticket_unique_ticket ON booking_ticket (ticket_id);

CREATE INDEX IF NOT EXISTS booking_ticket_by_booking ON booking_ticket (booking_id);

CREATE UNIQUE INDEX IF NOT EXISTS identity_registry_unique_email ON identity_registry (email);

CREATE UNIQUE INDEX IF NOT EXISTS identity_request_signature_unique_signature ON identity_request_signature (signature);

CREATE UNIQUE INDEX IF NOT EXISTS performance_artist_unique_pair ON performance_artist (performance_id, user_id);

CREATE INDEX IF NOT EXISTS performance_artist_by_performance ON performance_artist (performance_id);

CREATE INDEX IF NOT EXISTS performance_artist_by_user ON performance_artist (user_id);

