CREATE INDEX IF NOT EXISTS performance_by_production_start ON performance (production_id, starts_at);

CREATE INDEX IF NOT EXISTS performance_by_venue_start ON performance (venue_id, starts_at);

CREATE INDEX IF NOT EXISTS production_by_status ON production (status);

