CREATE INDEX IF NOT EXISTS rehearsal_by_venue_start ON rehearsal (venue_id, starts_at);

CREATE INDEX IF NOT EXISTS rehearsal_requirement_by_production_category_status ON rehearsal_requirement (production_id, category, status);

